// Factory for SW-03..07: an event/feature that is satisfied when detected, or
// automatically satisfied when the SW is generated by Workbox/a plugin
// (SPEC §4 — avoids false negatives of pattern-matching). Skips if SW-01 fails.

import type { Check } from '../../../core/check.js';
import { info, pass, skip, warn } from '../../../core/finding.js';
import type { CheckModule } from '../../../core/module.js';
import { messages } from '../../../report/messages.js';
import { type SwAnalysis, loadServiceWorker } from './shared.js';

export interface SwFeatureSpec {
  check: Check;
  satisfied(a: SwAnalysis): boolean;
  /** Extra evidence when satisfied. */
  evidence?(a: SwAnalysis): string | undefined;
  /** If true, a generated (Workbox) SW does NOT auto-satisfy this check. */
  ignoreWorkbox?: boolean;
}

export function swFeature(spec: SwFeatureSpec): CheckModule {
  const { check } = spec;
  return {
    check,
    dependsOn: ['SW-01'],
    async run(ctx) {
      if (!ctx.results.passed('SW-01')) return skip(check, 'dependency');
      const m = messages[check.id] ?? {};
      const { analysis } = await loadServiceWorker(ctx);
      if (!spec.ignoreWorkbox && analysis.workboxGenerated) {
        return pass(check, m.managed ?? m.ok);
      }
      if (spec.satisfied(analysis)) {
        return pass(check, m.ok, spec.evidence?.(analysis));
      }
      const msg = m.missing ?? '';
      const fix = m.fix ?? '';
      return check.severity === 'warning' ? warn(check, msg, fix) : info(check, msg, fix);
    },
  };
}
